// Who gets the hearts, filled in when the template is added.
const WHO = {{who}};
const PLUM = '#3a1830';
const BLUSH = '#ffe3ec';
const PINK = '#ff8fb0';
const HEART = 'M12 21s-7.5-4.6-9.6-9.3C.9 8.2 3 4.5 6.6 4.5c2.1 0 3.6 1.2 5.4 3.2 1.8-2 3.3-3.2 5.4-3.2 3.6 0 5.7 '
  + '3.7 4.2 7.2C19.5 16.4 12 21 12 21z';
// The key: a disc with the heart cut out, so the heart still shows in tinted and clear mode.
const KEY = 'M24 0A24 24 0 1 0 24 48A24 24 0 1 0 24 0Z M24 33s-7.5-4.6-9.6-9.3C12.9 20.2 15 16.5 18.6 16.5c2.1 0 '
  + '3.6 1.2 5.4 3.2 1.8-2 3.3-3.2 5.4-3.2 3.6 0 5.7 3.7 4.2 7.2C31.5 28.4 24 33 24 33z';

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the number are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const d = ctx.data;
  const line = (value) => ({ type: 'text', value, size: 12.5 * u, weight: 'semibold', color: BLUSH, opacity: 0.8,
    lineLimit: 1, minScale: 0.6, frame: { height: 16.25 * u, alignment: 'leading' } });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: PLUM,
    children: [
      { type: 'vstack', align: 'leading', spacing: 0,
        padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: HEART, viewBox: [0, 0, 24, 24], fill: PINK, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: WHO, size: 13 * u, weight: 'bold', color: PINK, lineLimit: 1, minScale: 0.4 } ] },
          { type: 'text', value: d.received, fontName: 'Bricolage Grotesque Display', size: 36 * u,
            kerning: -1.08 * u, color: BLUSH, accent: true, lineLimit: 1, minScale: 0.5, padding: { top: 4.4 * u } },
          { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 1.4 * u },
            frame: { maxWidth: ctx.family === 'small' ? 112 * u : 200 * u, alignment: 'leading' },
            children: [
              line(d.received > 0 ? 'from ' + WHO + ' today' : 'No hearts yet'),
              d.sent > 0 && line('you sent ' + d.sent),
            ] },
        ] },
      { type: 'zstack', padding: 13 * u,
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomTrailing' },
        children: [
          { type: 'button', action: 'send', children: [
            { type: 'path', d: KEY, viewBox: [0, 0, 48, 48], fill: '#ff6f8c', accent: true,
              frame: { width: 46 * u, height: 46 * u }, shadow: { color: '#0000004D', radius: 5 * u, y: 4 * u } } ] },
        ] },
    ],
  };
}
